    constructor(C _c) { c = _c; }

    // Drive the contract: initialize, set an initial MinSum, then attempt to change it.
    // Parameters:
    // initVal: initial MinSum to set before initialization
    // newVal: value passed to SetMinSum after initialization
    function run(uint initVal, uint newVal) public {
        // Set initial MinSum before initializing
        c.SetMinSum(initVal);
        // Mark contract initialized
        c.Initialized();
        // Read MinSum after initialization (should be initVal on P)
        uint before = c.MinSum();
        // Attempt to change MinSum after initialization
        c.SetMinSum(newVal);
        // Read MinSum after the attempted change
        uint after = c.MinSum();
        // On the original contract P, after must equal before (SetMinSum should have reverted when initialized).
        // On the mutant M (which allows unconditional assignment), after may differ from before.
        assert(after == before);
    }
}

