pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: an amount to put and then try to collect; actor is the depositor
    function testFuzz_property(uint256 seedAmount) public {
        // keep amount reasonable and non-zero
        uint256 amount = bound(seedAmount, 1, 1 ether);

        // deploy a helper log contract that will revert on call to simulate an external failing callee
        ReverterLog rev = new ReverterLog();

        // set MinSum and Log using initial setup (must be done before Initialized())
        c.SetMinSum(0);
        c.SetLogFile(address(rev));

        // mark initialized so SetLogFile cannot be called afterwards in reference contract
        c.Initialized();

        // prepare an actor who will deposit and then call Collect; give them funds
        address actor = address(0xABCD);
        vm.deal(actor, amount);
        vm.startPrank(actor);
        // deposit via Put with some lockTime 0
        c.Put{value: amount}(0);
        // try to Collect: this will cause the contract to call msg.sender.call which will target the actor
        // but actor is an EOA here so that external call from C to msg.sender is to an EOA and succeeds; however
        // the important external call that differs between reference and mutant is SetLogFile's assignment site
        // We instead rely on observing whether SetLogFile can be called after Collect by attempting it.
        // First, call Collect
        bool ok;
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // Now: In the reference contract, since SetLogFile previously set Log and Initialized was set true,
        // SetLogFile should revert (intitalized==true). But we want to assert a UNIVERSAL property that Collect does not
        // flip ability to call SetLogFile when it was callable before. To realize that as a fuzzed property,
        // instead we will reset a fresh contract where intitalized was false, then perform actions routing external
        // interactions through a reverter helper to trigger the mutant difference.

        // For the final single assertion required by the harness, we re-deploy a fresh contract and run the
        // distinguishing scenario using the adversarial callee whose fallback reverts. The property to assert:
        // After using Collect where msg.sender is a reverting contract, SetLogFile remains callable (does not revert) on reference,
        // while mutant may have set intitalized=true earlier and thus would revert. We assert that calling SetLogFile now does NOT revert.

        // Deploy fresh instance
        C c2 = new C();
        // Prepare a depositor which is a contract that accepts funds but when C calls it during Collect will revert; also it can receive funds initially
        RevertingRecipient depositor = new RevertingRecipient();
        // fund depositor
        vm.deal(address(depositor), amount);

        // Before initialization, SetMinSum and SetLogFile must be callable
        c2.SetMinSum(0);
        // set Log to depositor address (this is allowed because intitalized is false)
        c2.SetLogFile(address(depositor));
        // do NOT call Initialized() so intitalized remains false in reference

        // Have depositor deposit into c2 by calling Put via its self-executed call
        depositor.doPut{value: amount}(address(c2), 0);

        // Now attempt to Collect from depositor (the call into msg.sender from c2 will target depositor and will revert)
        // Use try/catch to swallow any revert
        try depositor.callCollect(address(c2), amount) {
            // ignored
        } catch {
            // ignored
        }

        // Finally, after the Collect attempt, the reference guarantees that SetLogFile is still callable (intitalized remained false),
        // so calling SetLogFile should NOT revert. We check that by calling it and ensuring it does NOT revert.
        bool setOk;
        try c2.SetLogFile(address(0x1234)) {
            setOk = true;
        } catch {
            setOk = false;
        }

        // Single assertion: in the correct contract this must be true for all inputs; the mutant (which sets intitalized=true inside SetLogFile)
        // can cause this to be false for some inputs. We assert that SetLogFile did not revert.
        assertTrue(setOk);
    }
}

// Helper that will revert on any call (used as the Log target to make Collect's internal call fail)
contract ReverterLog {
    fallback() external payable {
        revert("revert log");
    }
}

// Depositor contract that can deposit into C and then call Collect via an external call so that C's msg.sender.call targets this contract
contract RevertingRecipient {
    // accept funds
    receive() external payable {}

    function doPut(address caddr, uint256 lock) external payable {
        C(caddr).Put{value: msg.value}(lock);
    }

    // call Collect on C as this contract
    function callCollect(address caddr, uint256 am) external returns (bool) {
        try C(caddr).Collect(am) {
            return true;
        } catch {
            return false;
        }
    }
}

